//go:build amd64 && !purego

package keccak

import (
	"os"
	"strings"
)

// permuteAVX512 is generated by internal/gen (keccakf_avx512_amd64.s).
//
//go:noescape
func permuteAVX512(a *[25]uint64)

// absorbAVX512 XORs n consecutive Rate-byte blocks starting at p into a,
// applying the permutation after each block. It reads exactly n*Rate bytes.
//
//go:noescape
func absorbAVX512(a *[25]uint64, p *byte, n int)

// cpuid and xgetbv are implemented in cpu_amd64.s.
func cpuid(leaf, subleaf uint32) (eax, ebx, ecx, edx uint32)
func xgetbv() (eax, edx uint32)

// useAVX512 reports whether the AVX-512 kernel is used. It is decided once,
// at package initialisation, from CPUID/XGETBV and GODEBUG.
var useAVX512 = detectAVX512()

func detectAVX512() bool {
	maxLeaf, _, _, _ := cpuid(0, 0)
	var ecx1, ebx7, xcr0 uint32
	if maxLeaf >= 1 {
		_, _, ecx1, _ = cpuid(1, 0)
	}
	if ecx1&cpuidOSXSAVE != 0 {
		// XGETBV may only be executed when OSXSAVE is set.
		xcr0, _ = xgetbv()
	}
	if maxLeaf >= 7 {
		_, ebx7, _, _ = cpuid(7, 0)
	}
	return avx512Usable(maxLeaf, ecx1, xcr0, ebx7) && !godebugDisablesAVX512(os.Getenv("GODEBUG"))
}

const (
	cpuidOSXSAVE   = 1 << 27 // CPUID.1:ECX
	cpuidAVX512F   = 1 << 16 // CPUID.(7,0):EBX
	cpuidAVX512VL  = 1 << 31 // CPUID.(7,0):EBX
	xcr0ZMMEnabled = 1<<1 | 1<<2 | 1<<5 | 1<<6 | 1<<7
	// XCR0 bits: SSE(1), AVX(2), opmask(5), ZMM_Hi256(6), Hi16_ZMM(7).
)

// avx512Usable is the pure decision rule, separated for table tests.
func avx512Usable(maxLeaf, ecx1, xcr0, ebx7 uint32) bool {
	if maxLeaf < 7 || ecx1&cpuidOSXSAVE == 0 {
		return false
	}
	if xcr0&xcr0ZMMEnabled != xcr0ZMMEnabled {
		return false
	}
	return ebx7&cpuidAVX512F != 0 && ebx7&cpuidAVX512VL != 0
}

// godebugDisablesAVX512 honours the GODEBUG switches the Go runtime uses
// for CPU features, so operators can force the portable kernel (for
// example on a CPU with a known AVX-512 erratum). Each required feature
// (AVX512F, AVX512VL) has its own state, processed left to right:
//
//   - cpu.avx512f=on|off and cpu.avx512vl=on|off set that feature;
//   - cpu.avx512=on|off sets both (SILA alias);
//   - cpu.all=off disables both; cpu.all accepts only "off", as in Go;
//   - any other value is ignored.
//
// "on" never enables hardware support; it only cancels an earlier "off".
// The AVX-512 kernel is disabled if any required feature ends up off.
func godebugDisablesAVX512(godebug string) bool {
	f, vl := true, true
	for _, kv := range strings.Split(godebug, ",") {
		k, v, ok := strings.Cut(strings.TrimSpace(kv), "=")
		if !ok || (v != "on" && v != "off") {
			continue
		}
		on := v == "on"
		switch k {
		case "cpu.all":
			if !on {
				f, vl = false, false
			}
		case "cpu.avx512":
			f, vl = on, on
		case "cpu.avx512f":
			f = on
		case "cpu.avx512vl":
			vl = on
		}
	}
	return !(f && vl)
}

// maxBlocksPerAsmCall bounds the time spent inside one non-preemptible
// assembly call (64 blocks = 8704 bytes, roughly 15 µs on the reference
// machine), so a huge input cannot delay a garbage-collection
// stop-the-world or goroutine preemption for the whole hash.
const maxBlocksPerAsmCall = 64

func permute(a *[25]uint64) {
	if useAVX512 {
		permuteAVX512(a)
		return
	}
	permuteGeneric(a)
}

// absorb XORs len(data)/Rate full blocks into a, permuting after each.
// Trailing bytes beyond the last full block are ignored.
func absorb(a *[25]uint64, data []byte) {
	n := len(data) / Rate
	if n == 0 {
		return
	}
	if !useAVX512 {
		absorbGeneric(a, data[:n*Rate])
		return
	}
	for n > 0 {
		k := min(n, maxBlocksPerAsmCall)
		absorbChunkAVX512(a, &data[0], k)
		data = data[k*Rate:]
		n -= k
	}
}

// absorbChunkAVX512 exists only to be a preemption point. The assembly
// kernel is a leaf function with no stack-check prologue, so the Go
// scheduler cannot stop it. This wrapper is not inlined and calls another
// function, so it gets a prologue in which a pending preemption request
// (for example a GC stop-the-world) is honoured between chunks.
//
//go:noinline
func absorbChunkAVX512(a *[25]uint64, p *byte, n int) { absorbAVX512(a, p, n) }
